CREATE TABLE IF NOT EXISTS mesario_waitlist (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, voter_id bigint NOT NULL REFERENCES voters(id), status text NOT NULL DEFAULT 'waiting', urna_id bigint REFERENCES urnas(id), created_at timestamptz NOT NULL DEFAULT now(), assigned_at timestamptz); CREATE UNIQUE INDEX IF NOT EXISTS mesario_waitlist_active_voter ON mesario_waitlist(voter_id) WHERE status IN ('waiting','assigned');